import{_ as s,o as a,c as r,a2 as t}from"./chunks/framework.YT-FC_Xx.js";const u=JSON.parse('{"title":"凭据、到期与流量","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription-users.md","filePath":"guide/subscription-users.md","lastUpdated":1795229750000}'),e={name:"guide/subscription-users.md"};function i(l,o,n,c,d,g){return a(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="凭据、到期与流量" tabindex="-1">凭据、到期与流量 <a class="header-anchor" href="#凭据、到期与流量" aria-label="Permalink to &quot;凭据、到期与流量&quot;">​</a></h1><p>订阅可以分给别人用：每个订阅有自己的凭据，可以设到期日期和流量上限，到期或用完自动断开。</p><h2 id="独立凭据" tabindex="-1">独立凭据 <a class="header-anchor" href="#独立凭据" aria-label="Permalink to &quot;独立凭据&quot;">​</a></h2><ul><li>每个订阅有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li>可以设到期日期（到期当天 23:59 后断开）和流量上限，留空就是不限</li><li><strong>停用</strong>、<strong>删除</strong> 或 <strong>到期</strong> 后，面板会把它的凭据从服务器上删掉，已导入的配置也连不上了</li><li><strong>重置链接和凭据</strong>：旧链接和对方已导入的配置立即失效，适合链接泄露时使用</li><li>支持单独凭据的协议：VLESS、VMess、Trojan、Hysteria2、TUIC、AnyTLS、NaïveProxy、SOCKS5、HTTP，以及启用独立密码的 Xray Shadowsocks。未开启此选项的 Shadowsocks、Snell、WireGuard 和导入节点仍使用共用凭据；订阅停用后，客户端保存的配置仍能连接（界面标出“共用凭据”）。</li><li>3 天内到期会推送 <a href="./notify">通知</a></li></ul><h3 id="shadowsocks-独立密码" tabindex="-1">Shadowsocks 独立密码 <a class="header-anchor" href="#shadowsocks-独立密码" aria-label="Permalink to &quot;Shadowsocks 独立密码&quot;">​</a></h3><p>在 Xray 的 Shadowsocks 入站打开「每个订阅使用独立密码」，再把这个入站加入分发订阅使用的节点组。各订阅连接同一端口，使用不同的凭据，流量和限额分开计算。</p><ul><li><strong>传统 Shadowsocks</strong>：支持 <code>aes-128-gcm</code>、<code>aes-256-gcm</code> 和 <code>chacha20-ietf-poly1305</code>，不要求客户端支持 SS2022。</li><li><strong>SS2022</strong>：支持 <code>2022-blake3-aes-128-gcm</code> 和 <code>2022-blake3-aes-256-gcm</code>；不支持 SS2022 ChaCha20 多用户。订阅会下发 <code>服务器密钥:用户密钥</code>，客户端必须支持 SS2022 多用户，仅支持普通 SS2022 的客户端可能无法连接。</li></ul><p>该选项默认关闭。建议先在新端口测试；对现有入站开启时，旧共享密码不再生效，客户需刷新分发订阅。不提供不计量的共享链接，也不能把该入站选作 FLYX 的出站代理或分流出口，或与高级 JSON 配置同时使用。节点需要支持订阅流量计数；没有可计量的有效订阅时，该入站不监听。</p><h2 id="流量上限" tabindex="-1">流量上限 <a class="header-anchor" href="#流量上限" aria-label="Permalink to &quot;流量上限&quot;">​</a></h2><ul><li>每个订阅单独统计流量（上传 + 下载），可以设 <strong>流量上限</strong>，用完自动断开，和到期一样</li><li><strong>每月重置</strong>：选每月几号，到那天 0 点自动清零；也可以在订阅详情里点 <strong>重置流量</strong> 手动清零，超限断开的会立即恢复</li><li>用到 90% 和用完时会推送 <a href="./notify">通知</a>，概览页的“需要处理”里也会列出</li><li>客户端里能看到已用流量、总量和到期时间（<code>Subscription-Userinfo</code>）</li><li>有的手机客户端不显示上面这些信息：在订阅的 <strong>基本</strong> 里打开 <strong>在节点列表显示到期和流量</strong>，节点列表最前面会多两个占位节点，名字是「⏳ 到期 2026-12-31」和「📊 剩余 70.00GB / 100.00GB」（不限流量时显示已用）。它们连不上，只用来看</li><li>停用、到期或流量用完后，订阅链接不再报错，而是返回一份只有一个占位节点的配置，名字写明原因（「⚠️ 订阅已过期，请联系管理员」等），对方更新订阅后在客户端里就能看到；原来的节点和凭据不会下发</li><li>统计在节点所在的服务器上进行：每个订阅走自己的出站，服务器用 nftables 计数，Xray 和 sing-box 都支持。需要服务器上有 nftables，并且 agent 要和面板一起更新到最新版（旧 agent 能正常转发，只是不计数）</li><li>只统计支持单独凭据的节点。使用共用凭据的节点分不清是谁在用，不计入。</li></ul><h2 id="流量统计" tabindex="-1">流量统计 <a class="header-anchor" href="#流量统计" aria-label="Permalink to &quot;流量统计&quot;">​</a></h2><p>订阅详情里切到 <strong>流量统计</strong>，可以按 <strong>小时</strong>（近 24 小时）、<strong>日</strong>（近 30 天）、<strong>月</strong>（近 12 个月）查看：</p><ul><li>这段时间的下载、上传和合计</li><li>下载 / 上传折线图，点（或悬停）某个点看那个时间的流量</li><li>明细列表，最新的在前</li><li>图上的虚线是 <strong>本周期起</strong>：订阅创建或上次重置的时间</li></ul><p>统计范围和流量上限一样，按查看者的时区分日、分月。新记录按 15 分钟汇总，可正确处理半小时、45 分钟时差；旧的小时记录跨本地时间边界时会按时长分配，并显示估算提示。<strong>重置流量</strong> 只清零已用量，不影响历史统计；历史保留约 13 个月，删除订阅时一起删除。3.3.29 起开始记录，之前的流量没有历史。</p><p>流量历史仍保留 400 天，以覆盖近 12 个月视图。持续有流量时，每个订阅每天的汇总记录由 24 条增至 96 条，约为原来的四倍，400 天约 38,400 条；仅有流量的时段会写入，实际表和索引占用取决于活跃订阅数量。升级前应预留相应数据库空间；监控明细的保留天数设置不影响订阅流量历史。</p><p>订阅上方的 <strong>已用流量</strong> 和这里的合计不一定相等：已用流量从本周期开始（创建或上次重置，详情里写着“X 起的上传 + 下载合计”）一直累计，这里只算所选的近 24 小时 / 30 天 / 12 个月。比如重置后已用量归零，近 30 天里仍有重置前的流量；3.3.29 之前用掉的流量算在已用量里，但图里没有。</p>',16)])])}const p=s(e,[["render",i]]);export{u as __pageData,p as default};
